/* eslint-disable @typescript-eslint/no-unused-expressions */

import Uint64 = require( '@stdlib/number/uint64/ctor' );
import ArrayBuffer = require( '@stdlib/array/buffer' );
import Uint64Array = require( './index' );

/**
* Callback function.
*
* @param v - input value
* @returns output value
*/
function clbk( v: Uint64 ): Uint64 {
	return Uint64.of( v.hi * 2,  v.lo * 2 );
}


// TESTS //

// The function returns a 64-bit unsigned integer array...
{
	new Uint64Array(); // $ExpectType Uint64Array
	Uint64Array(); // $ExpectType Uint64Array
	new Uint64Array( 2 ); // $ExpectType Uint64Array
	Uint64Array( 2 ); // $ExpectType Uint64Array
	new Uint64Array( [ 1 ] ); // $ExpectType Uint64Array
	Uint64Array( [ 1 ] ); // $ExpectType Uint64Array

	const buf = new ArrayBuffer( 8 );
	new Uint64Array( buf ); // $ExpectType Uint64Array
	Uint64Array( buf ); // $ExpectType Uint64Array
	new Uint64Array( buf, 4 ); // $ExpectType Uint64Array
	Uint64Array( buf, 4 ); // $ExpectType Uint64Array
	new Uint64Array( buf, 4, 1 ); // $ExpectType Uint64Array
	Uint64Array( buf, 4, 1 ); // $ExpectType Uint64Array
}

// The compiler throws an error if the function is provided a first argument that is not a number, typed array, array-like object, or array buffer...
{
	new Uint64Array( true ); // $ExpectError
	new Uint64Array( false ); // $ExpectError
	new Uint64Array( null ); // $ExpectError
	new Uint64Array( 'abc' ); // $ExpectError
	new Uint64Array( {} ); // $ExpectError
	new Uint64Array( ( x: number ): number => x ); // $ExpectError

	Uint64Array( true ); // $ExpectError
	Uint64Array( false ); // $ExpectError
	Uint64Array( null ); // $ExpectError
	Uint64Array( 'abc' ); // $ExpectError
	Uint64Array( {} ); // $ExpectError
	Uint64Array( ( x: number ): number => x ); // $ExpectError
}

// The compiler throws an error if the function is provided a second argument that is not a number...
{
	const buf = new ArrayBuffer( 8 );
	new Uint64Array( buf, true ); // $ExpectError
	new Uint64Array( buf, false ); // $ExpectError
	new Uint64Array( buf, null ); // $ExpectError
	new Uint64Array( buf, 'abc' ); // $ExpectError
	new Uint64Array( buf, {} ); // $ExpectError
	new Uint64Array( buf, ( x: number ): number => x ); // $ExpectError

	Uint64Array( buf, true ); // $ExpectError
	Uint64Array( buf, false ); // $ExpectError
	Uint64Array( buf, null ); // $ExpectError
	Uint64Array( buf, 'abc' ); // $ExpectError
	Uint64Array( buf, {} ); // $ExpectError
	Uint64Array( buf, ( x: number ): number => x ); // $ExpectError
}

// The compiler throws an error if the function is provided a third argument that is not a number...
{
	const buf = new ArrayBuffer( 8 );
	new Uint64Array( buf, 4, true ); // $ExpectError
	new Uint64Array( buf, 4, false ); // $ExpectError
	new Uint64Array( buf, 4, null ); // $ExpectError
	new Uint64Array( buf, 4, 'abc' ); // $ExpectError
	new Uint64Array( buf, 4, {} ); // $ExpectError
	new Uint64Array( buf, 4, ( x: number ): number => x ); // $ExpectError

	Uint64Array( buf, 4, true ); // $ExpectError
	Uint64Array( buf, 4, false ); // $ExpectError
	Uint64Array( buf, 4, null ); // $ExpectError
	Uint64Array( buf, 4, 'abc' ); // $ExpectError
	Uint64Array( buf, 4, {} ); // $ExpectError
	Uint64Array( buf, 4, ( x: number ): number => x ); // $ExpectError
}

// The `from` method returns a 64-bit unsigned integer array...
{
	Uint64Array.from( [ 1 ] ); // $ExpectType Uint64Array
	Uint64Array.from( [ 1 ], ( x: number ): number => x * x ); // $ExpectType Uint64Array
	Uint64Array.from( [ new Uint64( 1 ) ], clbk, {} ); // $ExpectType Uint64Array
}

// The compiler throws an error if the `from` method is provided a first argument which is not array-like or iterable...
{
	Uint64Array.from( true ); // $ExpectError
	Uint64Array.from( false ); // $ExpectError
	Uint64Array.from( 123 ); // $ExpectError
	Uint64Array.from( null ); // $ExpectError
	Uint64Array.from( {} ); // $ExpectError

	Uint64Array.from( true, clbk ); // $ExpectError
	Uint64Array.from( false, clbk ); // $ExpectError
	Uint64Array.from( 123, clbk ); // $ExpectError
	Uint64Array.from( null, clbk ); // $ExpectError
	Uint64Array.from( {}, clbk ); // $ExpectError

	Uint64Array.from( true, clbk, {} ); // $ExpectError
	Uint64Array.from( false, clbk, {} ); // $ExpectError
	Uint64Array.from( 123, clbk, {} ); // $ExpectError
	Uint64Array.from( null, clbk, {} ); // $ExpectError
	Uint64Array.from( {}, clbk, {} ); // $ExpectError
}

// The compiler throws an error if the `from` method is provided a second argument which is not a function with a supported signature...
{
	Uint64Array.from( [ 1 ], true ); // $ExpectError
	Uint64Array.from( [ 1 ], false ); // $ExpectError
	Uint64Array.from( [ 1 ], 123 ); // $ExpectError
	Uint64Array.from( [ 1 ], null ); // $ExpectError
	Uint64Array.from( [ 1 ], {} ); // $ExpectError
}

// The `of` method returns a 64-bit unsigned integer array...
{
	Uint64Array.of( 1, 1, 1, 1 ); // $ExpectType Uint64Array
}

// The compiler throws an error if the `of` method is provided arguments that are not numbers...
{
	Uint64Array.of( 'abc', 'def' ); // $ExpectError
	Uint64Array.of( true, false ); // $ExpectError
	Uint64Array.of( {}, [] ); // $ExpectError
	Uint64Array.of( null, null ); // $ExpectError
}
